for lang in PAYOUT:
    path = ROOT / lang / "emails.json"
    data = json.loads(path.read_text(encoding="utf-8"))
    changed = False
    if data.get("payoutDelayed") != PAYOUT[lang]:
        data["payoutDelayed"] = PAYOUT[lang]; changed = True
    ov = data.setdefault("overpayment", {})
    for k, v in OVERPAY[lang].items():
        if ov.get(k) != v: ov[k] = v; changed = True
    if changed:
        path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"{lang}: {'updated' if changed else 'up to date'}")
